  for (const item of items) {
    const k = keyOf(item);
    counts.set(k, (counts.get(k) ?? 0) + 1);
  }
  return counts;
}

function partition<T>(items: T[], keep: (item: T) => boolean) {
  const yes: T[] = [], no: T[] = [];
  for (const item of items) (keep(item) ? yes : no).push(item);
  return { yes, no };
}

function groupBy<T>(items: T[], keyOf: (item: T) => string) {
  const groups = new Map<string, T[]>();
  for (const item of items) {
    const k = keyOf(item);
    const bucket = groups.get(k);
    if (bucket) bucket.push(item);
    else groups.set(k, [item]);
  }
  return groups;
}

function groupBySorted<T>(items: T[], keyOf: (item: T) => string, compare: (a: T, b: T) => number) {
  const groups = new Map<string, T[]>();
  for (const item of items) {
    const k = keyOf(item);
    if (!groups.has(k)) groups.set(k, []);
    groups.get(k)!.push(item);
  }
  for (const bucket of groups.values()) bucket.sort(compare);
  return groups;
}

