function memoizeSuccess<K, V>(load: (key: K) => Promise<V>) {
  const cache = new Map<K, V>();
  return async (key: K): Promise<V> => {
    const hit = cache.get(key);
    if (hit !== undefined) return hit;
    const value = await load(key);
    cache.set(key, value);
    return value;
  };
}

function memoizeAll<K, V>(load: (key: K) => Promise<V>) {
  const cache = new Map<K, Promise<V>>();
  return (key: K): Promise<V> => {
    const hit = cache.get(key);
    if (hit) return hit;
    const p = load(key);
    cache.set(key, p);
    return p;
  };
}

function memoizeLast<K, V>(load: (key: K) => Promise<V>) {
  let lastKey: K | undefined, lastValue: V | undefined, has = false;
  return async (key: K): Promise<V> => {
    if (has && key === lastKey) return lastValue as V;
    const value = await load(key);
    lastKey = key;
    lastValue = value;
    has = true;
    return value;
  };
}

function memoizeTtl<K, V>(load: (key: K) => Promise<V>, ttlMs: number) {
  const cache = new Map<K, { value: V; expires: number }>();
  return async (key: K): Promise<V> => {
    const hit = cache.get(key);
    if (hit && hit.expires > Date.now()) return hit.value;
    const value = await load(key);
    cache.set(key, { value, expires: Date.now() + ttlMs });
    return value;
  };
}

function dedupeInflight<K, V>(load: (key: K) => Promise<V>) {
  const inflight = new Map<K, Promise<V>>();
  return (key: K): Promise<V> => {
    const running = inflight.get(key);
    if (running) return running;
    const p = load(key).finally(() => inflight.delete(key));
    inflight.set(key, p);
    return p;
  };
}

