class TokenBucket {
  private tokens: number;
  private last = Date.now();
  constructor(private ratePerSec: number, private burst: number) {
    this.tokens = burst;
  }
  tryAcquire(): boolean {
    const now = Date.now();
    this.tokens = Math.min(this.burst, this.tokens + ((now - this.last) / 1000) * this.ratePerSec);
    this.last = now;
    if (this.tokens < 1) return false;
    this.tokens -= 1;
    return true;
  }
}

class FixedWindowLimiter {
  private windowStart = Date.now();
  private used = 0;
  constructor(private ratePerSec: number, private burst: number) {}
  tryAcquire(): boolean {
    const now = Date.now();
    if (now - this.windowStart >= 1000) {
      this.windowStart = now;
      this.used = 0;
    }
    if (this.used >= Math.min(this.ratePerSec, this.burst)) return false;
    this.used++;
    return true;
  }
}

class QueuingLimiter {
  private nextAllowed = 0;
  constructor(private intervalMs: number) {}
  async acquire(): Promise<void> {
    const now = Date.now();
    const wait = Math.max(0, this.nextAllowed - now);
    this.nextAllowed = Math.max(now, this.nextAllowed) + this.intervalMs;
    await new Promise((r) => setTimeout(r, wait));
  }
}

class HardCapLimiter {
