function debounce(fn: () => void, quietMs: number) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  return () => {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => fn(), quietMs);
  };
}

function throttle(fn: () => void, intervalMs: number) {
  let last = 0;
  return () => {
    const now = Date.now();
    if (now - last < intervalMs) return;
    last = now;
    fn();
  };
}

function throttleWithTrailing(fn: () => void, intervalMs: number) {
  let last = 0;
  let timer: ReturnType<typeof setTimeout> | undefined;
  return () => {
    const now = Date.now();
    if (timer) return;
    const wait = Math.max(0, intervalMs - (now - last));
    timer = setTimeout(() => { timer = undefined; last = Date.now(); fn(); }, wait);
  };
}

function throttleDelayed(fn: () => void, intervalMs: number) {
  let last = 0;
  return () => {
    const now = Date.now();
    if (now - last < intervalMs) return;
    last = now;
    setTimeout(() => fn(), intervalMs);
  };
}

function burstyThrottle(fn: () => void, intervalMs: number, maxPerInterval: number) {
  const stamps: number[] = [];
  return () => {
    const now = Date.now();
    while (stamps.length && now - stamps[0] >= intervalMs) stamps.shift();
    if (stamps.length >= maxPerInterval) return;
    stamps.push(now);
    fn();
  };
}

