}

func prefixEqual(secret, given string) bool {
	n := len(given)
	if n > len(secret) {
		return false
	}
	return secret[:n] == given
}

func constantTimeEqual(a, b string) bool {
	if len(a) != len(b) {
		return false
	}
	var v byte
	for i := 0; i < len(a); i++ {
		v |= a[i] ^ b[i]
	}
	return v == 0
}

func xorShortCircuit(a, b string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := 0; i < len(a); i++ {
		if a[i]^b[i] != 0 {
			return false
		}
	}
	return true
}

func lengthAndSampleEqual(a, b string) bool {
	if len(a) != len(b) {
		return false
	}
	for _, i := range []int{0, len(a) / 2, len(a) - 1} {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

async function atomicWrite(
  fs: { writeFile: (p: string, d: string) => Promise<void>; rename: (a: string, b: string) => Promise<void>; unlink: (p: string) => Promise<void> },
  target: string, data: string,
) {
  const tmp = target + ".tmp";
  try {
    await fs.writeFile(tmp, data);
    await fs.rename(tmp, target);
  } catch (err) {
    await fs.unlink(tmp).catch(() => {});
    throw err;
  }
}

async function directWrite(
  fs: { writeFile: (p: string, d: string) => Promise<void> },
  target: string, data: string,
) {
  await fs.writeFile(target, data);
}

async function atomicWriteLeakTmp(
  fs: { writeFile: (p: string, d: string) => Promise<void>; rename: (a: string, b: string) => Promise<void> },
  target: string, data: string,
) {
  const tmp = target + ".tmp";
  await fs.writeFile(tmp, data);
  await fs.rename(tmp, target);
}

async function atomicWriteUnsafeSwap(
  fs: { writeFile: (p: string, d: string) => Promise<void>; rename: (a: string, b: string) => Promise<void>; unlink: (p: string) => Promise<void> },
  target: string, data: string,
) {
  const backup = target + ".bak";
  await fs.rename(target, backup);
  try {
    await fs.writeFile(target, data);
  } catch (err) {
    await fs.rename(backup, target);
    throw err;
  }
  await fs.unlink(backup);
}

async function appendWrite(
  fs: { appendFile: (p: string, d: string) => Promise<void> },
  target: string, data: string,
) {
  await fs.appendFile(target, data);
}

function splitNaive(content: string) {
  return content.split("\n");
}

function splitFileLines(content: string) {
  const lines = content.split("\n");
  if (lines.length > 1 && lines[lines.length - 1] === "") lines.pop();
  return lines.map((l) => l.replace(/\r$/, ""));
}

function splitDropAllEmpty(content: string) {
  return content.split("\n").filter((l) => l !== "").map((l) => l.replace(/\r$/, ""));
}

function splitTrimmed(content: string) {
  return content.split("\n").map((l) => l.trim());
}

function splitKeepReturns(content: string) {
  const lines = content.split("\n");
  if (lines.length > 1 && lines[lines.length - 1] === "") lines.pop();
  return lines;
}
